<script lang="ts">
  import {portalToBody} from '../ui-portal';
  import NumberField from './ui/NumberField.svelte';
  import {onMount,tick,untrack} from 'svelte';
  import {X,ChevronLeft,ChevronRight,Table2} from '@lucide/svelte';
  import {Button} from './ui';
  import {editor} from '../core/editor.svelte';
  import {chartFromElement,chartNumber,validateChart,isRoundChart,type Chart} from '../core/charts';
  import {positionFloating} from '../ui-viewport';
  import {popoverFocus,restoreFocus} from '../ui-focus';
  let {elementId,initialSeries=0,initialCategory=0,pointMode=false,anchor,onlocation,onpreview,onclose,onfull}:{elementId:string;initialSeries?:number;initialCategory?:number;pointMode?:boolean;anchor:(series:number,category:number)=>HTMLElement|undefined;onlocation?:(series:number,category:number)=>void;onpreview:(chart:Chart|null)=>void;onclose:()=>void;onfull:()=>void}=$props();
  const deckId=editor.deck!.id,slideId=editor.slide!.id,origin=document.activeElement as HTMLElement|null;
  let revision=$state(editor.deck!.revision),category=$state(untrack(()=>initialCategory)),series=$state(untrack(()=>initialSeries)),label=$state(''),raw=$state(''),error=$state('');
  let popup=$state<HTMLDivElement>(),input=$state<HTMLInputElement>();let closing=false,frame=0;let focusOrigin:HTMLElement|undefined;
  const element=$derived(editor.slide?.elements.find(e=>e.id===elementId)),chart=$derived.by(()=>{try{return element?chartFromElement(element):undefined;}catch{return undefined;}});
  const stale=$derived(editor.deck?.id!==deckId||editor.slide?.id!==slideId||editor.deck?.revision!==revision||!element||element.locked);
  const analysis=$derived.by(()=>{try{if(!chart)throw new Error('Chart data is unavailable. Choose All data to review and repair the chart.');const labels=chart.labels.map((v,i)=>i===category?label:v),values=chart.series.map((v,j)=>j===series?{...v,values:v.values.map((n,i)=>i===category?chartNumber(raw):n)}:v);return {chart:validateChart({...chart,labels,series:values}),message:''};}catch(e){return {chart:undefined,message:(e as Error).message};}});
  const proposed=$derived(analysis.chart);
  $effect(()=>onpreview(stale?null:proposed??null));
  function position(){if(closing||!popup?.matches(':popover-open'))return;const node=anchor(series,category);focusOrigin=node;if(node)positionFloating(popup,node.getBoundingClientRect(),{preferredHeight:popup.scrollHeight,minHeight:pointMode?180:240,avoid:node.getBoundingClientRect()});}
  function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(position);}
  async function activate(){if(closing)return;label=chart?.labels[category]??'';raw=String(chart?.series[series]?.values[category]??'');error='';onlocation?.(series,category);await tick();if(closing)return;position();input?.focus({preventScroll:true});input?.select();}
  function commit(){if(stale){error='The document changed. Close and reopen these values.';return false;}if(!proposed){error=analysis.message;return false;}if(JSON.stringify(proposed)===JSON.stringify(chart)){onpreview(null);return true;}const before=editor.deck!.revision;editor.commit([{op:'update_element',slideId,elementId,patch:{chart:proposed,values:undefined}}],'','manual',revision);if(editor.deck!.revision===before){error=editor.error;return false;}revision=editor.deck!.revision;onpreview(null);return true;}
  function close(cancel=false,focus=true){
    if(closing)return true;if(!cancel&&!commit())return false;
    // Capture the logical target before onclose destroys the parent's keyed props.
    const target=focus?anchor(series,category):undefined,point=pointMode,key=target?.getAttribute('data-focus-key'),parent=target?.closest('[data-focus-scope]')?.parentElement,object=target?.closest<HTMLElement>('[data-element-id]');
    closing=true;onpreview(null);popup?.hidePopover();onclose();
    if(focus)void tick().then(()=>restoreFocus(point?(key?parent?.querySelector<HTMLElement>(`[data-focus-key="${CSS.escape(key)}"]`):target):object,origin));
    return true;
  }
  async function move(nextCategory:number,nextSeries=series){if(!commit())return;category=Math.max(0,Math.min((chart?.labels.length??1)-1,nextCategory));series=nextSeries;await activate();}
  function key(event:KeyboardEvent){if(event.isComposing||event.keyCode===229||event.key==='Tab')return;event.stopPropagation();if(event.key==='Escape'){event.preventDefault();close(true);}else if(event.key==='Enter'&&!event.altKey&&!event.metaKey&&!event.ctrlKey){event.preventDefault();const next=category+(event.shiftKey?-1:1);if(next<0||next>=(chart?.labels.length??0))close();else void move(next);}}
  onMount(()=>{series=isRoundChart(chart!)?chart!.pieSeries??0:Math.min(series,(chart?.series.length??1)-1);category=Math.min(category,(chart?.labels.length??1)-1);const p=popup!;p.showPopover();void activate();const resize=new ResizeObserver(schedule);resize.observe(p);window.addEventListener('resize',schedule);window.addEventListener('deck-studio-chart-rendered',schedule);document.addEventListener('scroll',schedule,true);window.visualViewport?.addEventListener('resize',schedule);window.visualViewport?.addEventListener('scroll',schedule);return()=>{closing=true;onpreview(null);resize.disconnect();cancelAnimationFrame(frame);window.removeEventListener('resize',schedule);window.removeEventListener('deck-studio-chart-rendered',schedule);document.removeEventListener('scroll',schedule,true);window.visualViewport?.removeEventListener('resize',schedule);window.visualViewport?.removeEventListener('scroll',schedule);p.hidePopover();};});
</script>
<!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
<div bind:this={popup} use:portalToBody use:popoverFocus={{close:()=>close(false,false),origin:()=>focusOrigin}} popover="auto" role="dialog" aria-label="Edit chart values" tabindex="-1" class="chart-value-editor ui-property-surface" onbeforetoggle={event=>{if(event.newState==='closed'&&!closing){if(commit()){closing=true;onpreview(null);onclose();}else queueMicrotask(()=>{popup?.showPopover();input?.focus({preventScroll:true});});}}} onkeydown={event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);}}}>
  <header><div class="point-name"><strong title={pointMode?label:undefined}>{pointMode?label:'Chart values'}</strong>{#if pointMode}<small>{chart?.series[series]?.name}</small>{/if}</div><div><Button variant="quiet" aria-label="Previous category" disabled={category===0||stale} onclick={()=>move(category-1)}><ChevronLeft size={16}/></Button><Button variant="quiet" aria-label="Next category" disabled={category===(chart?.labels.length??0)-1||stale} onclick={()=>move(category+1)}><ChevronRight size={16}/></Button><Button variant="quiet" aria-label="Cancel chart value edit" onclick={()=>close(true)}><X size={16}/></Button></div></header>
  <div class="value-editor-body">
  {#snippet pointDetails()}
  <div class="value-selectors"><label class="field-label">Series<select class="ui-property-input" aria-label="Chart series" disabled={Boolean(chart&&isRoundChart(chart))||stale} value={series} onchange={async event=>{const node=event.currentTarget;await move(category,Number(node.value));node.value=String(series);}}>{#each chart?.series??[] as s,j}<option value={j}>{s.name}</option>{/each}</select></label><label class="field-label">Category<select class="ui-property-input" aria-label="Chart category" value={category} disabled={stale} onchange={async event=>{const node=event.currentTarget;await move(Number(node.value));node.value=String(category);}}>{#each chart?.labels??[] as name,i}<option value={i}>{name}</option>{/each}</select></label></div>
  <label class="field-label">Category name<input class="ui-property-input" aria-label="Category name" maxlength="100" value={label} aria-invalid={!label.trim()} oninput={event=>{label=event.currentTarget.value;error='';}} onkeydown={key}/></label>
  {/snippet}
  {#if !pointMode}{@render pointDetails()}{/if}
  <NumberField label="Chart value" prefix="Value" preset="data" bind:input scopeKey={`${series}:${category}`} step="any" value={raw} invalid={!proposed} disabled={stale} oninput={value=>{raw=value;error='';}} onchange={value=>{raw=String(value);error='';}} onkeydown={key}/>
  {#if pointMode}<details class="point-details"><summary>Details</summary>{@render pointDetails()}</details>{/if}
  <p>Enter saves and moves down · Esc cancels · Undo is available</p>
  {#if stale||error||!proposed}<p class="error" role="alert">{error||(stale?'The document changed. Close and reopen these values.':analysis.message)}</p>{/if}
  </div>
  <footer><Button variant="quiet" disabled={stale||!proposed} onclick={()=>{if(commit()){onfull();close(true,false);}}}><Table2 size={16}/>All data</Button><Button variant="secondary" disabled={stale||!proposed} onclick={()=>close()}>Done</Button></footer>
</div>
<style>.point-name{min-width:0;flex:1;flex-direction:column;gap:2px!important}.point-name strong,.point-name small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.point-name small{font-size:var(--ui-meta);color:var(--text-secondary)}.point-details summary{font-size:var(--ui-label);cursor:pointer;padding:8px 0;min-height:36px}.point-details[open]{padding-bottom:8px}.chart-value-editor{position:fixed;inset:auto;margin:0;width:min(340px,calc(100vw - 24px));padding:12px;box-sizing:border-box;border:1px solid var(--component-border);border-radius:var(--r-popover);background:var(--dialog-surface);color:var(--text-primary);box-shadow:var(--shadow-popover);overflow:hidden;display:flex;flex-direction:column;overscroll-behavior:contain}.chart-value-editor header,.chart-value-editor footer{display:flex;justify-content:space-between;align-items:center;gap:8px}.chart-value-editor header>div{display:flex;gap:4px}.chart-value-editor header :global(button){padding:4px;min-width:36px;min-height:36px}.chart-value-editor strong{font-size:var(--ui-label);font-weight:600}.field-label{margin:12px 0;gap:4px}.value-selectors{display:grid;grid-template-columns:1fr 1fr;gap:12px}.value-selectors .field-label{min-width:0;margin-bottom:0}.field-label input,.field-label select{min-height:var(--property-control-height);background:var(--field-surface);border-color:var(--field-border)}.chart-value-editor p{font-size:var(--ui-meta);color:var(--text-secondary);line-height:var(--ui-line-reading);margin:8px 0}.chart-value-editor .error{color:var(--danger-text)}.value-editor-body{min-height:0;overflow:auto;overscroll-behavior:contain;flex:1;scrollbar-gutter:stable;}.chart-value-editor header,.chart-value-editor footer{flex:none}.chart-value-editor footer{padding-top:8px}@media(max-width:760px),(pointer:coarse){.chart-value-editor header :global(button),.chart-value-editor footer :global(button),.field-label input,.field-label select{min-height:44px}.chart-value-editor input{font-size:max(16px,var(--ui-body))}.point-details summary{min-height:44px}}</style>
